/*
 * node_modules/mochiglobals/index.js — installs web/Node globals the engine
 * does not provide natively, so ordinary Node/web code runs unchanged.
 *
 * The engine supplies only: queueMicrotask, performance, atob, btoa (and
 * mbjs:os timers). Everything else is shimmed here:
 *
 *   URL / URLSearchParams      -> mochiurl (SimpleURL fallback)
 *   TextEncoder / TextDecoder  -> UTF-8 impl in this file
 *   AbortController / AbortSignal
 *   structuredClone            -> structured JSON clone
 *   fetch                      -> mochiws.httpGet (GET/HEAD over WinHTTP)
 *   crypto                     -> mochicrypto (installs globalThis.crypto)
 *   setTimeout/...             -> mochitimers
 *
 * Importing this module is a side effect: it installs the globals. mochinode
 * imports it so any app that uses the shim layer gets them for free.
 */

import * as urlmod from '../mochiurl/index.js';
import * as timers from '../mochitimers/index.js';
import * as cryptoMod from '../mochicrypto/index.js';
import * as processMod from '../mochiprocess/index.js';

/* ---------------- TextEncoder / TextDecoder (UTF-8) ---------------- */

function utf8Encode(str) {
    const out = [];
    for (let i = 0; i < str.length; i++) {
        let code = str.codePointAt(i);
        if (code > 0xffff) i++; // consume surrogate pair
        if (code < 0x80) {
            out.push(code);
        } else if (code < 0x800) {
            out.push(0xc0 | (code >> 6), 0x80 | (code & 0x3f));
        } else if (code < 0x10000) {
            out.push(0xe0 | (code >> 12), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
        } else {
            out.push(0xf0 | (code >> 18), 0x80 | ((code >> 12) & 0x3f), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
        }
    }
    return Uint8Array.from(out);
}

function utf8Decode(bytes) {
    const buf = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
    let out = '';
    for (let i = 0; i < buf.length; ) {
        const b0 = buf[i];
        let code;
        let extra;
        if (b0 < 0x80) { code = b0; extra = 0; }
        else if ((b0 & 0xe0) === 0xc0) { code = b0 & 0x1f; extra = 1; }
        else if ((b0 & 0xf0) === 0xe0) { code = b0 & 0x0f; extra = 2; }
        else if ((b0 & 0xf8) === 0xf0) { code = b0 & 0x07; extra = 3; }
        else { code = 0xfffd; extra = 0; }
        if (i + extra >= buf.length) { out += '\ufffd'; break; }
        for (let k = 1; k <= extra; k++) code = (code << 6) | (buf[i + k] & 0x3f);
        out += String.fromCodePoint(code);
        i += extra + 1;
    }
    return out;
}

export class TextEncoder {
    constructor() { this.encoding = 'utf-8'; }
    encode(input = '') { return utf8Encode(String(input)); }
    encodeInto(input, dest) {
        const bytes = utf8Encode(String(input));
        const n = Math.min(bytes.length, dest.length);
        dest.set(bytes.subarray(0, n));
        return { read: n, written: n };
    }
}

export class TextDecoder {
    constructor(label = 'utf-8') { this.encoding = String(label).toLowerCase(); this.fatal = false; }
    decode(input) { return utf8Decode(input); }
}

/* ---------------- AbortController / AbortSignal ---------------- */

export class AbortSignal {
    constructor() { this.aborted = false; this.reason = undefined; this._listeners = []; }
    addEventListener(type, fn) { if (type === 'abort') this._listeners.push(fn); }
    removeEventListener(type, fn) { if (type === 'abort') this._listeners = this._listeners.filter((f) => f !== fn); }
    onabort = null;
    _fire() {
        this.aborted = true;
        this.reason = this.reason || new Error('Aborted');
        for (const fn of this._listeners) { try { fn(); } catch {} }
        if (this.onabort) try { this.onabort(); } catch {}
    }
    throwIfAborted() { if (this.aborted) throw this.reason; }
    static abort(reason) {
        const s = new AbortSignal();
        s.reason = reason || new Error('Aborted');
        s.aborted = true;
        return s;
    }
    static timeout(ms) {
        const s = new AbortSignal();
        timers.setTimeout(() => s._fire(), ms);
        return s;
    }
}

export class AbortController {
    constructor() { this.signal = new AbortSignal(); }
    abort(reason) { this.signal.reason = reason; this.signal._fire(); }
}

/* ---------------- structuredClone ---------------- */

function structuredCloneValue(value, seen) {
    if (value === null || typeof value !== 'object') {
        if (typeof value === 'function') return undefined;
        return value;
    }
    if (value instanceof Uint8Array) return value.slice();
    if (value instanceof Date) return new Date(value.getTime());
    if (value instanceof ArrayBuffer) return value.slice(0);
    if (seen.has(value)) return seen.get(value);
    if (Array.isArray(value)) {
        const copy = [];
        seen.set(value, copy);
        for (const item of value) copy.push(structuredCloneValue(item, seen));
        return copy;
    }
    const copy = {};
    seen.set(value, copy);
    for (const key of Object.keys(value)) {
        try { copy[key] = structuredCloneValue(value[key], seen); } catch {}
    }
    return copy;
}

export function structuredClone(value) {
    return structuredCloneValue(value, new Map());
}

/* ---------------- fetch (minimal GET/HEAD) ---------------- */

function bytesFromHex(hex) {
    const out = new Uint8Array(hex.length / 2);
    for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
    return out;
}

class FetchResponse {
    constructor(bodyBytes, status, statusText, headers) {
        this.body = bodyBytes;
        this.status = status;
        this.statusText = statusText;
        this.headers = headers || {};
        this.ok = status >= 200 && status < 300;
    }
    async text() { return utf8Decode(this.body); }
    async json() { return JSON.parse(utf8Decode(this.body)); }
    async arrayBuffer() { return this.body.buffer.slice(this.body.byteOffset, this.body.byteOffset + this.body.byteLength); }
    async blob() { return this.body; }
}

export async function fetch(input, init = {}) {
    const url = String(input);
    const method = String(init.method || 'GET').toUpperCase();
    if (method !== 'GET' && method !== 'HEAD') {
        throw new Error('mochiglobals: fetch only supports GET/HEAD (POST/PUT need native WinHTTP write)');
    }
    const wsmod = await import('../mochiws/index.js');
    if (!wsmod.isNativeReady()) throw new Error('mochiglobals: mochiws native unavailable');
    const raw = String(wsmod.httpGet(url));
    const statusKey = '"status":';
    const si = raw.indexOf(statusKey);
    const status = si >= 0 ? Number(raw.slice(si + statusKey.length, raw.indexOf(',', si))) : 0;
    const bodyKey = '"bodyHex":"';
    const bi = raw.indexOf(bodyKey);
    let bodyHex = '';
    if (bi >= 0) {
        const start = bi + bodyKey.length;
        const end = raw.indexOf('"', start);
        bodyHex = end >= 0 ? raw.slice(start, end) : '';
    }
    return new FetchResponse(bytesFromHex(bodyHex), status, status === 200 ? 'OK' : 'HTTP ' + status, {});
}

/* ---------------- install ---------------- */

function install() {
    const g = globalThis;
    if (cryptoMod && typeof cryptoMod.installGlobals === 'function') cryptoMod.installGlobals();
    if (typeof g.URL === 'undefined') { g.URL = urlmod.URL; g.URLSearchParams = urlmod.URLSearchParams; }
    if (typeof g.TextEncoder === 'undefined') g.TextEncoder = TextEncoder;
    if (typeof g.TextDecoder === 'undefined') g.TextDecoder = TextDecoder;
    if (typeof g.AbortController === 'undefined') g.AbortController = AbortController;
    if (typeof g.AbortSignal === 'undefined') g.AbortSignal = AbortSignal;
    if (typeof g.structuredClone === 'undefined') g.structuredClone = structuredClone;
    if (typeof g.fetch === 'undefined') g.fetch = fetch;
    timers.installGlobals();
    // Node globals the engine does not provide natively.
    if (typeof g.process === 'undefined') g.process = processMod;
    if (typeof g.global === 'undefined') g.global = g;
    if (typeof g.setImmediate !== 'function') g.setImmediate = timers.setImmediate;
    if (typeof g.clearImmediate !== 'function') g.clearImmediate = timers.clearImmediate;
    // console levels: the engine exposes only console.log; add the rest so
    // ordinary Node/web code that calls console.error/warn/info/debug works.
    if (typeof g.console !== 'object' || g.console === null) g.console = {};
    const clog = typeof g.console.log === 'function' ? g.console.log.bind(g.console) : () => {};
    if (typeof g.console.error !== 'function') g.console.error = (...a) => clog(...a);
    if (typeof g.console.warn !== 'function') g.console.warn = (...a) => clog(...a);
    if (typeof g.console.info !== 'function') g.console.info = (...a) => clog(...a);
    if (typeof g.console.debug !== 'function') g.console.debug = (...a) => clog(...a);
}

install();

export default { TextEncoder, TextDecoder, AbortController, AbortSignal, structuredClone, fetch, install };
